 libs/models/networkmodel.cpp     | 23 ++++++++++++++++++++++-
 libs/models/networkmodel.h       |  1 +
 libs/models/networkmodelitem.cpp | 17 +++++++++++++++++
 libs/models/networkmodelitem.h   |  4 ++++
 9 files changed, 99 insertions(+), 3 deletions(-)

