+void ConnectionIcon::addPortCarrierDevice(const NetworkManager::Device::Ptr &device)
+{
+    // Bridges and bonds wait in IP configuration until a port has a carrier: not shown as connecting
+    if (auto bridge = device.objectCast<NetworkManager::BridgeDevice>()) {
+        connect(bridge.data(), &NetworkManager::BridgeDevice::carrierChanged, this, &ConnectionIcon::setStates);
+    } else if (auto bond = device.objectCast<NetworkManager::BondDevice>()) {
+        connect(bond.data(), &NetworkManager::BondDevice::carrierChanged, this, &ConnectionIcon::setStates);
+    } else {
+        return;
+    }
+    connect(device.data(), &NetworkManager::Device::stateChanged, this, &ConnectionIcon::setStates);
+}
