+bool UiUtils::isWaitingForCarrier(const NetworkManager::Device::Ptr &device)
+{
+    if (!device || device->state() != NetworkManager::Device::ConfiguringIp) {
+        return false;
+    }
+
+    if (auto bridge = device.objectCast<NetworkManager::BridgeDevice>()) {
+        return !bridge->carrier();
+    }
+    if (auto bond = device.objectCast<NetworkManager::BondDevice>()) {
+        return !bond->carrier();
+    }
+
+    return false;
+}
